import{c as a,Q as s,j as p,m as t}from"./chunks/framework.DOi4mjdC.js";const _=JSON.parse('{"title":"调用样例","description":"","frontmatter":{},"headers":[{"level":1,"title":"调用样例","slug":"调用样例"}],"relativePath":"guide/编程指南/高级编程/高级特性/AI框架算子适配/ONNX框架/调用样例.md","filePath":"guide/编程指南/高级编程/高级特性/AI框架算子适配/ONNX框架/调用样例.md"}'),l={name:"guide/编程指南/高级编程/高级特性/AI框架算子适配/ONNX框架/调用样例.md"};function n(i,e,o,c,r,u){return s(),p("div",null,[...e[0]||(e[0]=[t(`<h1 id="调用样例" tabindex="-1">调用样例 <a class="header-anchor" href="#调用样例" aria-label="Permalink to &quot;调用样例&quot;">​</a></h1><p>完成了ONNX框架的适配插件开发后，即可实现从ONNX框架调用Ascend C自定义算子。下面以一个仅包含LeakyRelu算子的ONNX框架网络为例（该网络中的LeakyRelu算子通过适配插件映射为自定义的LeakyRelu算子），呈现一个使用推理工具进行推理的过程，目的在于让您快速体验推理场景下网络中自定义算子调用的过程。</p><p>在完成如下步骤之前，您需要先参考上文内容完成自定义LeakyRelu算子kernel侧和host侧的开发、ONNX适配插件的开发，并完成算子的编译部署。</p><p>LeakyRelu算子实现的完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/02_features/00_compilation/custom_op" target="_blank" rel="noreferrer">LINK</a>。ONNX框架调用的完整示例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/02_features/02_framework/02_onnx" target="_blank" rel="noreferrer">LINK</a>。</p><ol><li><p>通过如下命令获取ONNX框架网络模型。作为示例，该模型中仅包含一个LeakyRelu算子。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>wget https://obs-9be7.obs.cn-east-2.myhuaweicloud.com/AscendC/leaky_relu.onnx</span></span></code></pre></div></li><li><p>执行如下命令生成离线模型。（如下命令中使用的目录以及文件均为样例，请以实际为准）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>atc --model=$HOME/module/leaky_relu.onnx --framework=5 --soc_version=&lt;soc_version&gt; --output=$HOME/module/out/leaky_relu --input_shape=&quot;X:8,16,1024&quot; --input_format=ND</span></span></code></pre></div><p>关键参数的解释如下：</p><ul><li><p>--model：ONNX框架网络模型文件（*.onnx）的路径。</p></li><li><p>--framework：原始框架类型。5表示ONNX。</p></li><li><p>--output：转换后的离线模型的路径以及文件名。请注意，记录保存该om模型文件的路径，后续开发应用时需要使用。</p></li><li><p>--soc_version：AI处理器的型号。</p></li><li><p>--input_shape：指定模型输入数据的shape，请基于算子支持的shape范围和实际使用场景进行设置，这里设置输入X为固定shape [8,16,1024]。</p></li><li><p>--input_format：指定模型输入数据的格式，请基于算子支持的格式和实际使用场景进行设置，这里配置为ND。</p></li></ul></li><li><p>使用export ASCEND_GLOBAL_LOG_LEVEL=1改变日志级别为INFO，若出现如下提示信息，则说明进入了Ascend C自定义算子编译流程且模型转换成功。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>...</span></span>
<span class="line"><span>start compile Ascend C operator LeakyReluCustom. kernel name is leaky_relu_custom</span></span>
<span class="line"><span>compile Ascend C operator: LeakyReluCustom success!</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>ATC run success</span></span></code></pre></div><p>成功执行命令后，在--output参数指定的路径下，可查看离线模型（如：leaky_relu.om）。</p></li><li><p>通过aclmdlExecute等接口在应用中加载模型执行推理。</p></li></ol>`,5)])])}const m=a(l,[["render",n]]);export{_ as __pageData,m as default};
